<?php namespace Workspace;
$hidden=static function(string $act,int $version=0,?int $sid=null) use($project,$week) {
    formFields($act); foreach (['project_id'=>$project,'week'=>$week,'version'=>$version,'sprint_id'=>$sid??''] as $k=>$v) echo '<input type="hidden" name="'.h($k).'" value="'.h($v).'">';
};
$selectedId=$sprint?(int)$sprint['id']:null;
$editable=$work&&(!$own||in_array($own['status'],['draft','rejected'],true));
?>
<p><a href="<?= h(url('project',['id'=>$project])) ?>">← <?= h($p['title']) ?></a></p>
<form method="get" class="inline"><input type="hidden" name="p" value="workload"><input type="hidden" name="project" value="<?= h($project) ?>"><label>Неделя (понедельник)<input type="date" name="week" value="<?= h($week) ?>" required></label><label>Спринт<select name="sprint"><?php selectOptions([''=>'Последний']+array_column($sprints,'title','id'),$selectedId) ?></select></label><button class="secondary">Открыть</button></form>
<?php if ($work): ?>
<section class="panel inset"><h2>Спринты</h2>
<?php if ($manage): ?><form method="post" class="formgrid"><?php $hidden('sprint.save') ?><label>Название нового спринта<input name="title" maxlength="180" required></label><label>Начало<input type="date" name="starts_on" required></label><label>Конец<input type="date" name="ends_on" required></label><button class="primary">Создать спринт</button></form><?php endif ?>
<?php if ($sprint): $sv=(int)$sprint['version']; $done=0; $estimate=0; foreach($sprintTasks as $st){$done+=(int)($sprint['state']==='closed'?(int)$st['completed_on_close']===1:$st['state']==='done'); $estimate+=(int)$st['estimate_minutes'];} ?>
<h3><?= h($sprint['title']) ?> · <?= h(SPRINT_STATES[$sprint['state']]) ?></h3><p><?= h($sprint['starts_on']) ?> — <?= h($sprint['ends_on']) ?> · Готово <?= h($done) ?>/<?= count($sprintTasks) ?> · План <?= h($estimate) ?> мин.</p>
<?php if ($manage&&$sprint['state']==='planned'): ?><form method="post" class="formgrid"><?php $hidden('sprint.save',$sv,$selectedId) ?><label>Название<input name="title" value="<?= h($sprint['title']) ?>" required maxlength="180"></label><label>Начало<input type="date" name="starts_on" value="<?= h($sprint['starts_on']) ?>" required></label><label>Конец<input type="date" name="ends_on" value="<?= h($sprint['ends_on']) ?>" required></label><button class="secondary">Сохранить</button></form><?php endif ?>
<?php foreach($sprintTasks as $st): ?><div class="splitrow"><div><a href="<?= h(url('task',['id'=>$st['task_id']])) ?>"><?= h($st['title']) ?></a><small><?= h($st['assignee']??'Без исполнителя') ?> · <?= h($st['estimate_minutes']) ?> мин. · <?= h($sprint['state']==='closed'?($st['completed_on_close']?'Готово при закрытии':'Не готово при закрытии'):STATES[$st['state']]) ?></small></div><?php if ($manage&&$sprint['state']!=='closed'): ?><form method="post" class="inline"><?php $hidden('sprint.task',$sv,$selectedId) ?><input type="hidden" name="task_id" value="<?= h($st['task_id']) ?>"><label>Минуты<input type="number" name="estimate_minutes" min="0" max="60000" value="<?= h($st['estimate_minutes']) ?>" required></label><button class="secondary">Сохранить</button><button class="secondary" name="remove" value="1">Убрать</button></form><?php endif ?></div><?php endforeach ?>
<?php if ($manage&&$sprint['state']!=='closed'): ?><form method="post" class="inline"><?php $hidden('sprint.task',$sv,$selectedId) ?><label>Номер задачи<input type="number" name="task_id" min="1" required list="workload-tasks"></label><label>Оценка, минут<input type="number" name="estimate_minutes" min="0" max="60000" required></label><button class="primary">Добавить задачу</button></form><form method="post"><?php $hidden('sprint.state',$sv,$selectedId) ?><button class="secondary" name="state" value="<?= $sprint['state']==='planned'?'active':'closed' ?>"><?= $sprint['state']==='planned'?'Начать спринт':'Закрыть спринт' ?></button></form><?php endif ?>
<?php else: ?><p>Спринтов ещё нет.</p><?php endif ?></section>
<section class="panel inset"><h2>Доступность · <?= h($week) ?> — <?= h(weekEnd($week)) ?></h2><p>Лимит времени на этот проект за неделю. Неуказанная доступность неизвестна; 0 означает отсутствие времени. Оценки задач выбранного спринта относятся ко всему спринту.</p>
<?php foreach($people as $uid=>$name): $a=$availability[$uid]??null; $planned=0; foreach($sprintTasks as $st) if ((int)$st['assignee_id']===(int)$uid) $planned+=(int)$st['estimate_minutes']; $actual=0; $approved=0; foreach($sheets as $sh) if ((int)$sh['user_id']===(int)$uid) { $actual+=(int)$sh['actual_minutes']; if ($sh['status']==='approved') $approved+=(int)$sh['total_minutes']; } ?><form method="post" class="inline"><?php $hidden('availability.save',(int)($a['version']??0),$selectedId) ?><input type="hidden" name="member_id" value="<?= h($uid) ?>"><label><?= h($name) ?> · план спринта <?= h($planned) ?> мин. · введено за неделю <?= h($actual) ?> мин. · согласовано <?= h($approved) ?> мин.<?php if ($a!==null && $actual>(int)$a['minutes']): ?> · <strong class="planning-warning">Превышение <?= h($actual-(int)$a['minutes']) ?> мин.</strong><?php endif ?><input type="number" name="minutes" min="0" max="10080" placeholder="Не задано" value="<?= h($a['minutes']??'') ?>" required></label><button class="secondary">Сохранить доступность</button></form><?php endforeach ?></section>
<datalist id="workload-tasks"><?php foreach($tasks as $t): ?><option value="<?= h($t['id']) ?>"><?= h($t['title']) ?></option><?php endforeach ?></datalist>
<?php if ($editable): ?><section class="panel inset"><h2>Мой таймшит</h2><p>Одна запись на задачу и день. Повторное сохранение заменяет её; 0 удаляет запись. Укажите фактические минуты.</p><form method="post" class="formgrid"><?php $hidden('time.save',(int)($own['version']??0),$selectedId) ?><label>Номер задачи<input type="number" name="task_id" min="1" list="workload-tasks" required></label><label>Дата<input type="date" name="worked_on" min="<?= h($week) ?>" max="<?= h(min(weekEnd($week),gmdate('Y-m-d'))) ?>" required></label><label>Минуты<input type="number" name="minutes" min="0" max="1440" required></label><label>Комментарий<input name="note" maxlength="500"></label><button class="primary">Сохранить время</button></form><?php if ($own&&(int)$own['actual_minutes']>0): ?><form method="post"><?php $hidden('time.submit',(int)$own['version'],$selectedId) ?><input type="hidden" name="sheet_id" value="<?= h($own['id']) ?>"><button class="primary">Отправить на согласование</button></form><?php endif ?></section><?php endif ?>
<?php endif ?>
<section class="panel inset"><h2>Недельный отчёт</h2><p>Согласовано в доступных вам таймшитах: <?= h($approvedMinutes) ?> мин. (<?= h(number_format($approvedMinutes/60,2,',',' ')) ?> ч).</p>
<?php if ($finance&&!$costVisible): ?><p>Для просмотра ставок и стоимости подтвердите MFA в разделе <a href="<?= h(url('security')) ?>">Безопасность</a>.</p><?php endif ?>
<?php if ($costVisible): ?><p>Согласованная почасовая стоимость: <?php if (!$costs): ?>нет<?php endif ?><?php foreach($costs as $currency=>$amount): ?><?= h(money($amount).' '.$currency) ?> · <?php endforeach ?></p><p>Текущая ставка: <?= $rate?h(RATE_MODES[$rate['mode']].' '.money((int)$rate['amount_minor']).' '.$rate['currency'].' / '.($rate['mode']==='hourly'?'час':'проект')):'не задана' ?>. Фиксированная цена не суммируется по таймшитам.</p>
<?php if ($user['role']==='owner'): ?><form method="post" class="formgrid"><?php $hidden('rate.save',(int)($rate['version']??0),$selectedId) ?><label>Тип ставки<select name="mode"><?php selectOptions(RATE_MODES,$rate['mode']??'hourly') ?></select></label><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES),$rate['currency']??'RUB') ?></select></label><label>Сумма<input name="amount" inputmode="decimal" value="<?= h($rate?money((int)$rate['amount_minor'],false):'') ?>" required></label><button class="primary">Сохранить ставку</button></form><?php endif ?><?php endif ?>
<?php foreach($sheets as $sh): ?><div class="panel inset"><h3><?= h($sh['name']) ?> · <?= h(TIME_STATES[$sh['status']]) ?> · <?= h($sh['actual_minutes']) ?> мин.</h3><?php if ($sh['decision_note']!==''): ?><p><?= h($sh['decision_note']) ?></p><?php endif ?>
<?php if ($costVisible&&in_array($sh['status'],['submitted','approved'],true)): ?><p>Ставка на момент отправки: <?= $sh['rate_mode']?h(RATE_MODES[$sh['rate_mode']].' '.money((int)$sh['rate_minor']).' '.$sh['rate_currency'].' · v'.$sh['rate_version']):'не задана' ?><?= $sh['cost_minor']!==null?' · '.h(money((int)$sh['cost_minor']).' '.$sh['rate_currency']):'' ?></p><?php endif ?>
<?php foreach($entries[$sh['id']]??[] as $e): ?><div class="splitrow"><span><?= h($e['worked_on'].' · #'.$e['task_id'].' '.$e['title'].' · '.$e['minutes'].' мин. · '.$e['note']) ?></span><?php if ($editable&&(int)$sh['user_id']===(int)$user['id']): ?><form method="post"><?php $hidden('time.save',(int)$sh['version'],$selectedId) ?><input type="hidden" name="task_id" value="<?= h($e['task_id']) ?>"><input type="hidden" name="worked_on" value="<?= h($e['worked_on']) ?>"><input type="hidden" name="minutes" value="0"><button class="secondary">Удалить</button></form><?php endif ?></div><?php endforeach ?>
<?php if ($manage&&$sh['status']==='submitted'&&(int)$sh['user_id']!==(int)$user['id']): foreach(['time.approve'=>'Согласовать','time.reject'=>'Вернуть'] as $act=>$label): ?><form method="post" class="inline"><?php $hidden($act,(int)$sh['version'],$selectedId) ?><input type="hidden" name="sheet_id" value="<?= h($sh['id']) ?>"><label>Комментарий<input name="decision_note" maxlength="500" <?= $act==='time.reject'?'required':'' ?>></label><button class="secondary"><?= h($label) ?> (MFA)</button></form><?php endforeach; endif ?></div><?php endforeach ?>
<?php if (!$sheets): ?><p>Нет таймшитов за выбранную неделю.</p><?php endif ?></section>
